"oldString": "class SERGate(FrameProcessor):\n    \"\"\"Holds LLMContextFrame until SER has annotated the current user message.\n\n    The gate is armed in ``on_user_turn_stopped`` (which fires before\n    ``user_aggregator`` pushes ``LLMContextFrame``) and released in\n    ``on_user_turn_audio_data`` after the emotion tag has been injected.\n    This guarantees the LLM always sees the emotion annotation.\n    \"\"\"\n\n    def __init__(self, timeout: float = 5.0):\n        super().__init__()\n        self._timeout = timeout\n        self._event = asyncio.Event()\n        self._event.set()  # Open by default — transparent until armed.\n\n    def arm(self):\n        \"\"\"Close the gate; call when a user turn ends.\"\"\"\n        self._event.clear()\n\n    def release(self):\n        \"\"\"Open the gate; call after SER completes (or fails).\"\"\"\n        self._event.set()\n\n    async def process_frame(self, frame, direction: FrameDirection):\n        await super().process_frame(frame, direction)\n        if direction == FrameDirection.DOWNSTREAM and isinstance(frame, LLMContextFrame):\n            try:\n                await asyncio.wait_for(self._event.wait(), timeout=self._timeout)\n            except asyncio.TimeoutError:\n                logger.warning(\n                    \"SERGate timed out — forwarding LLMContextFrame without emotion tag\"\n                )\n        await self.push_frame(frame, direction)\n\n\nclass RollingSERProcessor(FrameProcessor):\n    \"\"\"Maintains a rolling ring buffer of user audio and runs SER periodically.\n\n    During a long speaking turn, SER is run every ``window_secs`` seconds in\n    the background so the latest emotion is ready (or nearly ready) when the\n    turn ends. On ``UserStoppedSpeakingFrame``:\n\n    - Cached result (turn >= window_secs): emotion injected immediately,\n      ``SERGate`` released with **zero latency**.\n    - Short turn (< window_secs): SER runs on-demand on the ring buffer;\n      gate released when inference completes (~150-200 ms).\n\n    This replaces ``AudioBufferProcessor`` + ``on_user_turn_audio_data`` and\n    eliminates the race condition where ``LLMContextFrame`` reached the LLM\n    before SER completed.\n    \"\"\"\n\n    def __init__(\n        self,\n        context: LLMContext,\n        ser_gate: SERGate,\n        ser_func,  # run_ser_sync callable, or None when SER is disabled\n        *,\n        window_secs: float = 5.0,\n        sample_rate: int = 16000,\n    ):\n        super().__init__()\n        self._context = context\n        self._ser_gate = ser_gate\n        self._ser_func = ser_func\n        self._window_secs = window_secs\n        self._sample_rate = sample_rate\n        self._ring_buffer: bytearray = bytearray()\n        self._actual_sample_rate: int = sample_rate\n        self._user_speaking: bool = False\n        self._emotion_votes: list[str] = []  # one entry per periodic window\n        self._last_turn_emotion: str | None = None  # finalized emotion of most recent real audio stream\n        self._periodic_task = None\n        self._pending_injection: bool = False  # set True only when tagged=True\n\n    def request_injection(self) -> None:\n        \"\"\"Signal that the next _finalize_ser should inject the emotion tag.\"\"\"\n        self._pending_injection = True\n\n    # Matches only the live <session_state> block (no attributes).\n    # Does NOT match <session_state at=\"example-N\"> blocks in the examples section.\n    _LIVE_STATE_RE = re.compile(r'<session_state>(.*?)</session_state>', re.DOTALL)\n\n    def _inject_emotion(self, emotion: str) -> None:\n        \"\"\"Atomically replace the live <session_state> block with updated emotional_state.\"\"\"\n        messages = self._context.get_messages()\n        for i in range(len(messages)):\n            if messages[i].get(\"role\") == \"system\":\n                content = messages[i][\"content\"]\n                m = self._LIVE_STATE_RE.search(content)\n                if m:\n                    # Preserve existing <user_turn> if present.\n                    turn_match = re.search(r'<user_turn>\\d+</user_turn>', m.group(1))\n                    turn_part = f\"\\n  {turn_match.group(0)}\" if turn_match else \"\"\n                    new_block = (\n                        f\"<session_state>{turn_part}\"\n                        f\"\\n  <emotional_state>{emotion}</emotional_state>\"\n                        f\"\\n</session_state>\"\n                    )\n                    messages[i][\"content\"] = self._LIVE_STATE_RE.sub(new_block, content, count=1)\n                else:\n                    new_block = (\n                        f\"<session_state>\"\n                        f\"\\n  <emotional_state>{emotion}</emotional_state>\"\n                        f\"\\n</session_state>\"\n                    )\n                    messages[i][\"content\"] = content.rstrip(\"\\n\") + f\"\\n\\n{new_block}\"\n                logger.debug(\"_inject_emotion: set emotional_state='{}' in live session_state\", emotion)\n                return\n        # No system message found — create one.\n        self._context.add_message(\n            {\"role\": \"system\", \"content\": f\"<session_state>\\n  <emotional_state>{emotion}</emotional_state>\\n</session_state>\"}\n        )\n        logger.debug(\"_inject_emotion: created system message with emotional_state='{}'\", emotion)\n\n    async def process_frame(self, frame, direction: FrameDirection):\n        await super().process_frame(frame, direction)\n\n        if isinstance(frame, UserStartedSpeakingFrame):\n            self._user_speaking = True\n            self._ring_buffer.clear()\n            self._emotion_votes = []\n            self._actual_sample_rate = self._sample_rate\n            if self._ser_func is not None:\n                self._periodic_task = self.create_task(self._periodic_ser_loop())\n\n        elif isinstance(frame, UserStoppedSpeakingFrame):\n            self._user_speaking = False\n            if self._periodic_task is not None:\n                await self.cancel_task(self._periodic_task)\n                self._periodic_task = None\n            if self._ser_func is not None:\n                self.create_task(self._finalize_ser())\n\n        elif isinstance(frame, InputAudioRawFrame) and self._user_speaking:\n            # First real audio frame of a new turn — invalidate the previous\n            # turn's emotion so it cannot bleed into this turn's tag.\n            if not self._ring_buffer:\n                self._last_turn_emotion = None\n            # Keep only the last window_secs of speech audio (ring buffer).\n            self._actual_sample_rate = frame.sample_rate\n            self._ring_buffer.extend(frame.audio)\n            max_bytes = int(self._window_secs * self._actual_sample_rate * 2)\n            if len(self._ring_buffer) > max_bytes:\n                excess = len(self._ring_buffer) - max_bytes\n                del self._ring_buffer[:excess]\n\n        await self.push_frame(frame, direction)\n\n    async def _periodic_ser_loop(self) -> None:\n        \"\"\"Run SER every window_secs while the user is speaking.\"\"\"\n        while True:\n            await asyncio.sleep(self._window_secs)\n            if len(self._ring_buffer) < 320:  # < 10 ms — too short\n                continue\n            try:\n                emotion = await asyncio.to_thread(\n                    self._ser_func,\n                    bytes(self._ring_buffer),\n                    self._actual_sample_rate,\n                    self._window_secs,\n                )\n                self._emotion_votes.append(emotion)\n                logger.debug(\"SER (periodic): {} | votes so far: {}\", emotion, self._emotion_votes)\n            except Exception as exc:\n                logger.warning(\"Periodic SER failed: {}\", exc)\n\n    async def _finalize_ser(self) -> None:\n        \"\"\"Inject majority-vote emotion into context and release the SERGate.\"\"\"\n        try:\n            if self._emotion_votes:\n                # Majority vote over all periodic windows of this turn's audio.\n                # Ties broken by the most recent vote (last in list).\n                from collections import Counter\n                counts = Counter(self._emotion_votes)\n                emotion = max(self._emotion_votes, key=lambda e: (counts[e], self._emotion_votes[::-1].index(e) == 0))\n                logger.info(\n                    \"SER result (majority vote): {} | votes: {}\",\n                    emotion,\n                    dict(counts),\n                )\n                self._last_turn_emotion = emotion\n            elif len(self._ring_buffer) >= 320:\n                # Genuine short turn: run on-demand on this turn's audio.\n                emotion = await asyncio.to_thread(\n                    self._ser_func,\n                    bytes(self._ring_buffer),\n                    self._actual_sample_rate,\n                    self._window_secs,\n                )\n                logger.info(\"SER result (on-demand): {}\", emotion)\n                self._last_turn_emotion = emotion\n            elif self._last_turn_emotion is not None:\n                # Spurious sub-turn with no new audio (TranscriptionUserTurnStartStrategy\n                # fired UserStartedSpeakingFrame and wiped the buffer/votes).\n                # Reuse the already-finalized emotion from the same real audio stream.\n                emotion = self._last_turn_emotion\n                logger.info(\"SER result (reused from prior audio stream): {}\", emotion)\n            else:\n                emotion = \"neutral\"\n                logger.debug(\"SER: audio too short and no prior emotion, defaulting to neutral\")\n\n            if self._pending_injection:\n                self._inject_emotion(emotion)\n        except Exception as exc:\n            logger.warning(\"SER finalization failed — skipping emotion tag: {}\", exc)\n        finally:\n            self._pending_injection = False\n            self._ser_gate.release()\n\n\nasync def run_bot(transport: BaseTransport, runner_args: RunnerArguments):",
